using System;

// snake_case fields mirror data/generated/construction.json for JsonUtility (see CepaMapData).
#pragma warning disable IDE1006

namespace CepaCero.Building
{
    /// <summary>`cepacero.construction` v1, generated by tools/datagen from docs/construccion.md (D-022).</summary>
    [Serializable]
    public sealed class ConstructionData
    {
        public string format;
        public int version;
        public string source;
        public ConstructionRules rules;
        public ConstructionShape[] shapes;
        public ConstructionMaterial[] materials;
        public ConstructionRoof[] roofs;
        public ConstructionNatural[] naturals;

        /// <summary>Every block the data defines: shape × material, roofs and diggable ground, in a stable order.</summary>
        public ConstructionBlock[] blocks;
    }

    [Serializable]
    public sealed class ConstructionRules
    {
        /// <summary>Share of the damage a tool does to a material it is not meant for (0.25 = a quarter).</summary>
        public float wrong_tool_factor = 0.25f;

        /// <summary>Share of the cost given back when dismantling a piece.</summary>
        public float dismantle_refund = 0.5f;

        /// <summary>Noise radius (tiles) of digging.</summary>
        public float dig_noise = 9f;
    }

    [Serializable]
    public sealed class ConstructionShape
    {
        public string id;
        public string name;
        public string layer;
        public float units;
        public float hp_factor;
        public bool solid;
        public bool see_through;
        public bool opens;
        public int width;
        public int height;
        public string connects;
    }

    [Serializable]
    public sealed class ConstructionMaterial
    {
        public string id;
        public string name;
        public int hp;
        public string tool;
        public float noise;
        public float build_seconds;
        public bool paintable;
        public bool see_through;
        public string[] shapes;
        public ConstructionCost[] ingredients;
    }

    [Serializable]
    public sealed class ConstructionRoof
    {
        public string id;
        public string name;
        public int hp;
        public ConstructionCost[] ingredients;
    }

    [Serializable]
    public sealed class ConstructionNatural
    {
        public string id;
        public string name;
        public int hp;
        public string tool;
        public float noise;
        public string layer;
        public bool solid;
        public string connects;
        public ConstructionCost[] drops;
    }

    [Serializable]
    public sealed class ConstructionCost
    {
        public string item;
        public int count;
    }

    [Serializable]
    public sealed class ConstructionBlock
    {
        public string key;
        public string shape;
        public string material;
        public string layer;
        public int hp;
        public bool solid;
        public bool see_through;
        public int width;
        public int height;
        public string tool;
        public float noise;
        public bool paintable;
        public float build_seconds;
        public string connects;
        public string toggle_to;
        public bool is_open_variant;
        public ConstructionCost[] cost;
        public ConstructionCost[] drops;
    }
}
